package ai.eva.android.probe;
import java.nio.file.Path;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.pdf.PdfDocument;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.json.*;
/** Opt-in real Activity recreation checks, using only an isolated fixture. */
final class WorkspaceEditorUiProbe implements Application.ActivityLifecycleCallbacks {
 final Activity owner;final Handler handler=new Handler(Looper.getMainLooper());final JSONObject out=new JSONObject();Path fixture;String relative,pdfRelative;File draft;WorkspaceEditActivity editor;WorkspacePreviewActivity preview;int stage;boolean finished;long start;
 WorkspaceEditorUiProbe(Activity a){owner=a;}
 static void check(Activity activity){new WorkspaceEditorUiProbe(activity).begin();}
 void require(boolean ok,String why)throws IOException{if(!ok)throw new IOException(why);}
 void begin(){try{start=android.os.SystemClock.elapsedRealtime();Path workspace=WorkspaceFiles.root(owner).toPath();Path projects=workspace.resolve("projects");Files.createDirectories(projects);fixture=Files.createTempDirectory(projects,"editor-ui-check-");Path text=fixture.resolve("草稿.md");Files.write(text,"original".getBytes(StandardCharsets.UTF_8));relative=workspace.relativize(text).toString().replace('\\','/');draft=new File(new File(owner.getFilesDir(),"editor-drafts"),WorkspaceEditor.hash(relative.getBytes(StandardCharsets.UTF_8))+".json");
  Path pdf=fixture.resolve("pages.pdf");pdfRelative=workspace.relativize(pdf).toString().replace('\\','/');PdfDocument document=new PdfDocument();try{for(int i=0;i<2;i++){PdfDocument.Page page=document.startPage(new PdfDocument.PageInfo.Builder(300,400,i+1).create());page.getCanvas().drawColor(i==0?Color.WHITE:Color.LTGRAY);Paint paint=new Paint();paint.setTextSize(20);page.getCanvas().drawText("Page "+(i+1),20,30,paint);document.finishPage(page);}try(OutputStream output=new FileOutputStream(pdf.toFile())){document.writeTo(output);}}finally{document.close();}
  owner.getApplication().registerActivityLifecycleCallbacks(this);handler.postDelayed(()->{if(!finished)finish(new IOException("UI acceptance timed out at stage "+stage));},20000);owner.startActivity(new Intent(owner,WorkspaceEditActivity.class).putExtra("path",relative));
 }catch(Exception e){finish(e);}}
 public void onActivityResumed(Activity a){if(finished)return;if(a instanceof WorkspaceEditActivity&&relative.equals(a.getIntent().getStringExtra("path"))){editor=(WorkspaceEditActivity)a;handler.postDelayed(()->stepEditor((WorkspaceEditActivity)a),150);}else if(a instanceof WorkspacePreviewActivity&&pdfRelative.equals(a.getIntent().getStringExtra("path"))){preview=(WorkspacePreviewActivity)a;handler.postDelayed(()->stepPreview((WorkspacePreviewActivity)a),150);}}
 void stepEditor(WorkspaceEditActivity e){if(finished||e.isDestroyed())return;try{
  require(e.ready,"Editor failed to open");
  if(stage==0){require(e.editor.getText().toString().equals("original"),"Initial text mismatch");e.editor.setText("已保存 😀");e.save();require(new String(Files.readAllBytes(fixture.resolve("草稿.md")),StandardCharsets.UTF_8).equals("已保存 😀"),"UI save did not update file");out.put("nativeEditorSave",true);e.editor.setText("未保存草稿 😀");e.saveDraft();require(draft.isFile(),"Draft missing");stage=1;e.recreate();return;}
  if(stage==1){require(e.editor.getText().toString().equals("未保存草稿 😀"),"Draft lost on recreation");out.put("draftSurvivesActivityRecreation",true);Files.write(fixture.resolve("草稿.md"),"agent changed".getBytes(StandardCharsets.UTF_8));e.save();require(new String(Files.readAllBytes(fixture.resolve("草稿.md")),StandardCharsets.UTF_8).equals("agent changed"),"UI save overwrote agent change");require(e.editor.getText().toString().equals("未保存草稿 😀")&&draft.isFile(),"Conflict lost draft");out.put("uiConflictKeepsDraft",true);Files.delete(fixture.resolve("草稿.md"));stage=2;e.recreate();return;}
  if(stage==2){require(e.editor.getText().toString().equals("未保存草稿 😀"),"Deleted source blocks draft recovery");out.put("deletedFileDraftRecovery",true);stage=3;e.finish();owner.startActivity(new Intent(owner,WorkspacePreviewActivity.class).putExtra("path",pdfRelative));}
 }catch(Exception error){finish(error);}}
 void stepPreview(WorkspacePreviewActivity p){if(finished||p.isDestroyed())return;try{require(p.pdf!=null&&p.pdf.getPageCount()==2,"Native preview failed");if(stage==3){p.draw(1);require(p.number==1&&p.bitmap!=null,"Second PDF page not displayed");stage=4;p.recreate();return;}if(stage==4){require(p.number==1&&p.bitmap!=null,"PDF page lost on recreation");out.put("pdfPageSurvivesActivityRecreation",true);finish(null);}}catch(Exception e){finish(e);}}
 void finish(Exception error){if(finished)return;finished=true;handler.removeCallbacksAndMessages(null);owner.getApplication().unregisterActivityLifecycleCallbacks(this);if(editor!=null&&!editor.isDestroyed()){editor.ready=false;editor.finish();}if(preview!=null&&!preview.isDestroyed())preview.finish();boolean cleaned=true;
  try{if(draft!=null){Files.deleteIfExists(draft.toPath());Files.deleteIfExists(Paths.get(draft.getPath()+".tmp"));}if(fixture!=null){Path projects=WorkspaceFiles.root(owner).toPath().resolve("projects");require(fixture.getParent().equals(projects)&&fixture.getFileName().toString().startsWith("editor-ui-check-"),"Cleanup boundary mismatch");try(java.util.stream.Stream<Path> stream=Files.walk(fixture)){for(Path path:(Iterable<Path>)stream.sorted(Comparator.reverseOrder())::iterator)Files.delete(path);}}}catch(Exception e){cleaned=false;if(error==null)error=e;}
  try{out.put("result",error==null?"PASS":"FAIL").put("fixtureCleanup",cleaned).put("elapsedMs",android.os.SystemClock.elapsedRealtime()-start).put("systemPickerTested",false);if(error!=null)out.put("error",error.toString());}catch(Exception ignored){}owner.getSharedPreferences("eva-workspace-check",0).edit().putString("editorUi",out.toString()).commit();android.widget.Toast.makeText(owner,"Editor UI check: "+out.optString("result"),1).show();
 }
 public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}
}
